(function executeRule(current, previous) {
    // Only trigger for the 'Submit Green Idea' catalog item
    var idea = new GlideRecord('u_green_ideas');
    idea.initialize();
    idea.short_description = 'Green Idea: ' + current.cat_item.getDisplayValue();
    idea.u_requested_item = current.sys_id;
    idea.u_idea_summary = current.variables.idea_summary;
    idea.u_estimated_savings = current.variables.estimated_savings;
    idea.u_department = current.variables.department;
    idea.insert();
    gs.log('Green Idea record created for RITM: ' + current.number, 'GreenIdea');
})(current, previous);
